import { readTestData } from "../test-utils.mjs";

// Generated by 🤖
async function testTypedSelect(debug = false) {
	try {
		const { wasmBuffer } = await readTestData("select/select-typed.wat", debug);
		const { instance } = await WebAssembly.instantiate(wasmBuffer, {});

		const i32Tests = [
			{
				name: "select_i32_1",
				expected: 1,
				func: "select_i32",
				params: [1, 1, 0],
			},
			{
				name: "select_i32_2",
				expected: 0,
				func: "select_i32",
				params: [0, 1, 0],
			},
			{
				name: "select_i32_3",
				expected: 10,
				func: "select_i32",
				params: [1, 10, 20],
			},
			{
				name: "select_i32_4",
				expected: 20,
				func: "select_i32",
				params: [0, 10, 20],
			},
		];

		const i64Tests = [
			{
				name: "select_i64_1",
				expected: 100n,
				func: "select_i64",
				params: [1, 100n, 200n],
			},
			{
				name: "select_i64_2",
				expected: 200n,
				func: "select_i64",
				params: [0, 100n, 200n],
			},
			{
				name: "select_i64_3",
				expected: 9007199254740991n,
				func: "select_i64",
				params: [1, 9007199254740991n, 1n],
			},
		];

		const f32Tests = [
			{
				name: "select_f32_1",
				expected: 1.5,
				func: "select_f32",
				params: [1, 1.5, 3.5],
			},
			{
				name: "select_f32_2",
				expected: 3.5,
				func: "select_f32",
				params: [0, 1.5, 3.5],
			},
		];

		const f64Tests = [
			{
				name: "select_f64_1",
				expected: 3.14,
				func: "select_f64",
				params: [1, 3.14, 2.71],
			},
			{
				name: "select_f64_2",
				expected: 2.71,
				func: "select_f64",
				params: [0, 3.14, 2.71],
			},
			{
				name: "select_f64_3",
				expected: 1.5,
				func: "select_f64",
				params: [1, 1.5, 2.5],
			},
		];

		const allTests = [...i32Tests, ...i64Tests, ...f32Tests, ...f64Tests];
		const results = [];

		for (const { name, expected, func, params } of allTests) {
			const result = instance.exports[func](...params);
			// Handle BigInt comparisons for i64 tests
			const resultRes =
				typeof expected === "bigint"
					? result === expected
					: Math.abs(result - expected) < 0.0001; // Allow small float differences
			console.assert(
				resultRes,
				`❌ ${name} should return ${expected}, got ${result}`,
			);
			results.push(resultRes);

			if (debug) {
				console.log(`Debug: ${name} - Expected: ${expected}, Got: ${result}`);
			}

			if (resultRes) {
				console.log(`✅ ${name} test passed!`);
			} else {
				console.error(`❌ ${name} test failed.`);
			}
		}

		// Check if all tests passed
		const allTestsPassed = results.every((result) => result);
		if (allTestsPassed) {
			console.log("✅ All typed select tests passed!");
			return true;
		}
		console.error("❌ Some typed select tests failed.");
		return false;
	} catch (error) {
		console.error("❌ Error testing typed select:", error);
		return false;
	}
}

export default testTypedSelect;
